//! 🎟️ Stored PNG bytes are allocated, emitted and retired under the initiating caller's original grants.
use super::{PngRasterSource,RasterImage};
use semio_framework_value::{RetainedAllocationEffect,OriginalRetirementPoll,RetainedWorkPoll,ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,retained_clone::{RetainedCloneClose,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
#[derive(semio_framework_value::RetireOwned)]
#[value(send_only)]
struct PngData<S:PngRasterSource>{source:S,bytes:Vec<u8>}
pub struct PngEncodeWork<S:PngRasterSource=RasterImage>{data:ManuallyDrop<Option<PngData<S>>>,close:RetainedCloneClose,width:u32,height:u32,total:usize,encoded:usize,zlib:usize,cursor:usize,phase:u8,at:usize,block_at:usize,block_length:usize,block_final:bool,crc:u32,adler_a:u32,adler_b:u32,closing:bool,failed:bool}
fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn crc(mut crc:u32,value:u8)->u32{crc^=u32::from(value);for _ in 0..8{crc=(crc>>1)^if crc&1!=0{0xedb88320}else{0};}crc}
impl<S:PngRasterSource> PngEncodeWork<S>{
 pub fn new(source:S,maximum_bytes:usize)->Result<Self,(ValueError,S)>{let image=source.raster();if super::validate_image(image).is_err(){return Err((fault("png.original-image-invalid"),source))}let width=image.width;let height=image.height;let total=match image.pixels.len().checked_add(height as usize){Some(total)=>total,None=>return Err((fault("png.original-extent-overflow"),source))};let zlib=match total.checked_add(total.div_ceil(4096)*5+6){Some(value)=>value,None=>return Err((fault("png.original-extent-overflow"),source))};let encoded=match zlib.checked_add(57){Some(value)=>value,None=>return Err((fault("png.original-extent-overflow"),source))};if !(8..=67_108_864).contains(&maximum_bytes)||encoded>maximum_bytes{return Err((fault("png.original-output-limit"),source))}Ok(Self{data:ManuallyDrop::new(Some(PngData{source,bytes:Vec::new()})),close:Default::default(),width,height,total,encoded,zlib,cursor:0,phase:0,at:0,block_at:0,block_length:0,block_final:false,crc:0xffffffff,adler_a:1,adler_b:0,closing:false,failed:false})}
 pub fn source(&self)->&RasterImage{self.data.as_ref().expect("PNG original source remains owned").source.raster()}
 pub fn output_ready(&self)->bool{!self.closing&&!self.failed&&self.phase==5}
 fn body(body:usize)->Result<usize,ValueError>{if !(1..=32768).contains(&body){return Err(fault("png.original-body-invalid"))}Ok(body.min(4096))}
 pub fn demands(&self,body:usize)->Result<RetirementDemand,ValueError>{let body=Self::body(body)?;if self.closing||self.failed||self.phase>5{return Err(fault("png.original-inactive"))}Ok(match self.phase{0=>RetirementDemand{capacity_bytes:self.encoded,depth:1,..Default::default()},1=>RetirementDemand{copy_bytes:43,depth:1,..Default::default()},2=>RetirementDemand{copy_bytes:5,depth:1,..Default::default()},3=>RetirementDemand{copy_bytes:(body/2).max(1).min(self.block_length-self.block_at)*2,depth:1,..Default::default()},4=>RetirementDemand{copy_bytes:20,depth:1,..Default::default()},_=>RetirementDemand{depth:1,..Default::default()}})}
 fn put(&mut self,byte:u8){self.data.as_mut().unwrap().bytes.push(byte);self.at+=1;}
 fn write(&mut self,byte:u8){self.put(byte);self.crc=crc(self.crc,byte);}
 fn header(&self,at:usize,header_crc:u32)->u8{const SIGNATURE:[u8;8]=[137,80,78,71,13,10,26,10];match at{0..=7=>SIGNATURE[at],8..=11=>13u32.to_be_bytes()[at-8],12..=15=>b"IHDR"[at-12],16..=19=>self.width.to_be_bytes()[at-16],20..=23=>self.height.to_be_bytes()[at-20],24=>8,25=>6,26..=28=>0,29..=32=>(header_crc^0xffffffff).to_be_bytes()[at-29],33..=36=>(self.zlib as u32).to_be_bytes()[at-33],37..=40=>b"IDAT"[at-37],41=>0x78,_=>0x01}}
 pub fn advance(&mut self,body:usize,grant:RetainedCloneGrant)->RetainedWorkOutcome{let demand=match self.demands(body){Ok(value)=>value,Err(error)=>return RetainedWorkOutcome{result:Err(error),work:0}};if !retained_clone_grant_admits(grant,demand){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}let mut progress=RetainedCloneProgress{copied_items:1,..Default::default()};let mut work:u128=1;
 let result=(||{match self.phase{0=>{let bytes=&mut self.data.as_mut().unwrap().bytes;if bytes.try_reserve_exact(self.encoded).is_err(){return Err(fault("png.original-allocation-refused"))}progress.retained_capacity_bytes=bytes.capacity();self.phase=1;},1=>{let mut header_crc=0xffffffff;for at in 0..43{let byte=self.header(at,header_crc);self.put(byte);if (12..29).contains(&at){header_crc=crc(header_crc,byte)}if at>=37{self.crc=crc(self.crc,byte)}}progress.copied_bytes=43;work=43;self.phase=2;},2=>{self.block_length=(self.total-self.cursor).min(4096);self.block_final=self.cursor+self.block_length==self.total;let length=self.block_length as u16;for byte in [u8::from(self.block_final),length as u8,(length>>8)as u8,(!length)as u8,((!length)>>8)as u8]{self.write(byte)}self.block_at=0;self.phase=3;progress.copied_bytes=5;work=5;},3=>{let count=demand.copy_bytes/2;let stride=self.width as usize*4+1;for _ in 0..count{let column=self.cursor%stride;let byte=if column==0{0}else{self.source().pixels[self.cursor/stride*(stride-1)+column-1]};self.write(byte);self.cursor+=1;self.block_at+=1;self.adler_a=(self.adler_a+u32::from(byte))%65521;self.adler_b=(self.adler_b+self.adler_a)%65521;}progress.copied_bytes=count*2;work=count as u128;if self.block_at==self.block_length{self.phase=if self.block_final{4}else{2}}},4=>{let adler=(self.adler_b<<16)|self.adler_a;for byte in adler.to_be_bytes(){self.write(byte)}let end=self.crc^0xffffffff;for byte in end.to_be_bytes(){self.put(byte)}for byte in [0,0,0,0,b'I',b'E',b'N',b'D',0xae,0x42,0x60,0x82]{self.put(byte)}progress.copied_bytes=20;work=20;if self.at!=self.encoded{return Err(fault("png.original-output-extent-mismatch"))}self.phase=5;},5=>{progress=Default::default();work=0;},_=>return Err(fault("png.original-phase"))}Ok(if self.phase==5{RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)})})();if result.is_err(){self.failed=true}RetainedWorkOutcome{result:result.map_err(|error|error.with_retained_progress(progress)),work}}
 pub fn take_output(&mut self,grant:RetainedCloneGrant)->RetainedWorkOutcome<Option<(Vec<u8>,RetainedCloneProgress)>>{if !self.output_ready(){return RetainedWorkOutcome{result:Err(fault("png.original-output-unavailable")),work:0}}let bytes=std::mem::size_of::<Vec<u8>>();if grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<bytes{return RetainedWorkOutcome{result:Ok(None),work:0}}let output=std::mem::take(&mut self.data.as_mut().unwrap().bytes);self.phase=6;RetainedWorkOutcome{result:Ok(Some((output,RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}))),work:1}}
 pub fn cancel(&mut self){self.closing=true}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{self.close.next_owner_demands::<PngData<S>>(self.data.is_some(),&None,body)}
 pub fn close_step(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll{if !self.closing{return RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(fault("png.original-close-intent-required").into()),work:0})}if !self.close.is_empty(){return self.close.step_granted(body,effect)}let turn=self.close.begin_granted(&mut self.data,effect);RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Complete(Default::default()))).map_err(Into::into),work:turn.work})}
 pub fn terminal_is_empty(&self)->bool{self.data.is_none()&&self.close.is_empty()}
}
impl<S:PngRasterSource> Drop for PngEncodeWork<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original PNG private roots require funded close");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.data)}}}}
